def below_zero(operations: List[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def find_topmost_carpet(n, carpets, point) -> int:
    x, y = point
    for i in range(n - 1, -1, -1):
        a, b, g, k = carpets[i]
        if a <= x <= a + g and b <= y <= b + k:
            return i + 1
    return -1

def find_number_combinations():
    digits = [1,2,3,4,5,6,7,8,9]
    combos = []
    for i in digits:
        for j in digits:
            if j == i:
                continue
            for k in digits:
                if k == i or k == j:
                    continue
                first = i*100 + j*10 + k
                second = first * 2
                third = first * 3
                if second < 100 or second > 999 or third < 100 or third > 999:
                    continue
                # check digits of second
                d2_1 = second // 100
                d2_2 = (second // 10) % 10
                d2_3 = second % 10
                if d2_1 == 0 or d2_2 == 0 or d2_3 == 0:
                    continue
                if d2_1 == d2_2 or d2_1 == d2_3 or d2_2 == d2_3:
                    continue
                # check digits of third
                d3_1 = third // 100
                d3_2 = (third // 10) % 10
                d3_3 = third % 10
                if d3_1 == 0 or d3_2 == 0 or d3_3 == 0:
                    continue
                if d3_1 == d3_2 or d3_1 == d3_3 or d3_2 == d3_3:
                    continue
                combos.append((first, second, third))
    combos.sort(key=lambda x: x[0])
    return combos

def count_passing_ways(n, m):
    if m==0:
        return 1
    if n==1:
        return 0
    if n==2:
        return 1 if m%2==0 else 0
    dp_prev = [0]*n
    dp_prev[0] = 1
    for step in range(1, m+1):
        dp_cur = [0]*n
        for i in range(n):
            left = (i-1)%n
            right = (i+1)%n
            dp_cur[i] = dp_prev[left] + dp_prev[right]
        dp_prev = dp_cur
    return dp_prev[0]

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Convert a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    terms = []
    first_term = True
    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '+' if coeff > 0 else '-'

        abs_coeff = abs(coeff)

        # Determine coefficient string
        if abs_coeff == 1 and degree != 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        terms.append(f'{sign}{coeff_str}{var_str}')
        first_term = False

    if not terms:
        return '0'
    return ''.join(terms)

def string_transformation(A: str, B: str, rules: list) -> int | str:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps to find the minimum number of transformations.
    If impossible within 10 steps, returns "NO ANSWER!".
    """
    if A == B:
        return 0

    visited = {A}
    queue = [(A, 0)]

    while queue:
        current, steps = queue.pop(0)
        if steps >= 10:
            continue

        for src, tgt in rules:
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src) :]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                start = idx + 1  # allow overlapping replacements

    return "NO ANSWER!"

def remaining_trees_after_clearing(l, areas):
    if not areas:
        return l
    # Sort intervals by start
    sorted_areas = sorted(areas, key=lambda x: x[0])
    merged = []
    for start, end in sorted_areas:
        # Clamp to road bounds
        start = max(0, start)
        end = min(l, end)
        if start >= end:
            continue
        if not merged or start > merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    total_removed = sum(end - start for start, end in merged)
    remaining = l - total_removed
    return remaining if remaining >= 0 else 0

def calculate_arrangements(n, m, a) -> int:
    MOD = 10**6 + 7
    if m > sum(a):
        return 0
    dp_prev = [0] * (m + 1)
    dp_prev[0] = 1
    for i in range(n):
        limit = a[i]
        dp_cur = [0] * (m + 1)
        prefix = [0] * (m + 1)
        prefix[0] = dp_prev[0]
        for j in range(1, m + 1):
            prefix[j] = (prefix[j - 1] + dp_prev[j]) % MOD
        for j in range(m + 1):
            low = j - limit
            if low <= 0:
                dp_cur[j] = prefix[j]
            else:
                dp_cur[j] = (prefix[j] - prefix[low - 1]) % MOD
        dp_prev = dp_cur
    return dp_prev[m] % MOD

def minimum_students_to_leave(heights):
    n = len(heights)
    if n == 0:
        return 0

    # Longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Max length of a bitonic subsequence (increase then decrease)
    max_len = 0
    for i in range(n):
        # subtract 1 to avoid double counting the peak element
        current_len = lis[i] + lds[i] - 1
        if current_len > max_len:
            max_len = current_len

    return n - max_len
